#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
# Generate docs/build/SPIKES.md from the record files docs/build/spikes/*.md (BUILD_PLAN D-13).
#   ci/spikes-index.sh            write the generated file
#   ci/spikes-index.sh --check    exit 1 if the file differs from what would be generated
# Env (for tests): SPIKES_DIR (record files), SPIKES_OUT (generated file).
#
# Record file format (assumption: BUILD_PLAN D-13 names the fields, not their syntax):
#   file name  = <task ID>.md  (the ID, e.g. G-S5-HOST.md)
#   a line     "Verdict: <PASS|FAIL|...>"   (first one counts; the bold label "**Verdict:** PASS" is accepted too)
#   a line     "Measured: <value>"          (first one counts; same two label styles)
# A record with no Verdict line exits 1 naming the file (a field that cannot be read is never shown as a
# confident "(none)"). A missing Measured is listed as "(none)". Records are listed in byte order of the ID.
set -euo pipefail
export LC_ALL=C

root="$(cd "$(dirname "$0")/.." && pwd)"
dir="${SPIKES_DIR:-$root/docs/build/spikes}"
out="${SPIKES_OUT:-$root/docs/build/SPIKES.md}"

field() { # field <file> <Name>
  local v
  v="$(grep -m1 -E "^(\*\*)?$2:(\*\*)?([[:space:]]|\$)" "$1" | sed -E "s/^(\*\*)?$2:(\*\*)?[[:space:]]*//; s/[[:space:]]+\$//" || true)"
  if [ -z "$v" ] && [ "$2" = Verdict ]; then
    echo "spikes-index: $1 has no parsable 'Verdict:' line" >&2
    exit 1
  fi
  v="${v//|/\\|}"
  printf '%s' "${v:-(none)}"
}

generate() {
  printf '%s\n' '<!-- GENERATED by ci/spikes-index.sh from docs/build/spikes/*.md. Do not edit by hand. -->'
  printf '\n# Spike records\n\n'
  printf '| ID | Verdict | Measured |\n|---|---|---|\n'
  local f id verdict measured n=0
  if [ -d "$dir" ]; then
    while IFS= read -r f; do
      id="$(basename "$f" .md)"
      verdict="$(field "$f" Verdict)"
      measured="$(field "$f" Measured)"
      printf '| %s | %s | %s |\n' "$id" "$verdict" "$measured"
      n=$((n + 1))
    done < <(find "$dir" -maxdepth 1 -type f -name '*.md' | sort)
  fi
  if [ "$n" -eq 0 ]; then
    printf '| (no records yet) | | |\n'
  fi
}

# F-118: the 2 CP1 Fails-on cases that generating alone never judged.
#   1. The set of records equals A3 section 4's 8 spikes (SPIKES_REQUIRED, space separated; default below): a deleted or renamed record fails.
#   2. S1's rule (BUILD_PLAN D-1): write-to-client p95 under 5 s, else the verdict must not read PASS. Measured must carry "p95 <number> ms|s".
required="${SPIKES_REQUIRED-G-S1-SSE G-S2-TWA-OFFLINE G-S3-MAP-SAFARI G-S4-EXPO-DEVICE G-S5-HOST G-S6-EXPO-MAP G-S7-SWIFT G-S8-DATA-SIZES}"
s1id="${SPIKES_S1_ID-G-S1-SSE}"
judge() {
  local id missing=0 f verdict measured num unit ms
  for id in $required; do
    if [ ! -f "$dir/$id.md" ]; then
      echo "spikes-index: the spike record $id.md is missing (A3 section 4 names it)" >&2
      missing=1
    fi
  done
  f="$dir/$s1id.md"
  if [ -n "$s1id" ] && [ -f "$f" ]; then
    verdict="$(field "$f" Verdict)"
    measured="$(field "$f" Measured)"
    case "$verdict" in
      PASS*)
        if [[ "$measured" =~ p95[[:space:]]+([0-9]+(\.[0-9]+)?)[[:space:]]*(ms|s)([^a-z]|$) ]]; then
          num="${BASH_REMATCH[1]}"
          unit="${BASH_REMATCH[3]}"
          ms="$(awk -v n="$num" -v u="$unit" 'BEGIN { printf "%d", (u == "s" ? n * 1000 : n) }')"
          if [ "$ms" -ge 5000 ]; then
            echo "spikes-index: $s1id reads PASS with p95 $num $unit; S1 passes only under 5 s (else FAIL with D1)" >&2
            missing=1
          fi
        else
          echo "spikes-index: $s1id reads PASS but its Measured line has no 'p95 <number> ms|s' to judge" >&2
          missing=1
        fi
        ;;
    esac
  fi
  return "$missing"
}

case "${1:-}" in
  "")
    mkdir -p "$(dirname "$out")"
    generate > "$out"
    ;;
  --check)
    tmp="$(mktemp)"
    trap 'rm -f "$tmp"' EXIT
    generate > "$tmp"
    judge || exit 1
    if [ -f "$out" ] && cmp -s "$tmp" "$out"; then
      exit 0
    fi
    echo "spikes-index: $out differs from its generated form; run ci/spikes-index.sh and edit the record file instead" >&2
    exit 1
    ;;
  *)
    echo "usage: ci/spikes-index.sh [--check]" >&2
    exit 2
    ;;
esac
